B.Zm=new A.bI("Hayatta en hakiki m\xfcr\u015fit ilimdir.","Mustafa Kemal Atat\xfcrk",B.cj)
B.Z_=new A.bI("\xd6\u011frenmek zihni asla yormaz.","Leonardo da Vinci",B.cj)
B.Zs=new A.bI("E\u011fitim, d\xfcnyay\u0131 de\u011fi\u015ftirmek i\xe7in kullanabilece\u011fin en g\xfc\xe7l\xfc silaht\u0131r.","Nelson Mandela",B.cj)
B.Zb=new A.bI("Hayal g\xfcc\xfc bilgiden daha \xf6nemlidir.","Albert Einstein",B.cj)
B.Zr=new A.bI("Bilgi g\xfc\xe7t\xfcr.","Francis Bacon",B.cj)
B.YL=new A.bI("\u0130lim ilim bilmektir, ilim kendin bilmektir.","Yunus Emre",B.cj)
B.Z9=new A.bI("Okumak zihin i\xe7in neyse, egzersiz de beden i\xe7in odur.","Joseph Addison",B.cj)
B.Zj=new A.bI("Ne kadar \xe7ok okursan, o kadar \xe7ok \u015fey bilirsin.","Dr. Seuss",B.cj)
B.Zd=new A.bI("E\u011fitimin k\xf6kleri ac\u0131, meyveleri tatl\u0131d\u0131r.","Aristoteles",B.cj)
B.Z5=new A.bI("Hayatta hi\xe7bir \u015feyden korkulmamal\u0131, yaln\u0131zca anla\u015f\u0131lmal\u0131.","Marie Curie",B.cj)
B.YK=new A.bI("\xd6\u011frenmenin ya\u015f\u0131 yoktur.","T\xfcrk atas\xf6z\xfc",B.cj)
B.cW=new A.or("Emek",1,"emek")
B.YY=new A.bI("D\xe2hilik y\xfczde bir ilham, y\xfczde doksan dokuz terdir.","Thomas Edison",B.cW)
B.Z2=new A.bI("Hi\xe7bir \u015feye ihtiyac\u0131m\u0131z yok, yaln\u0131z bir \u015feye ihtiyac\u0131m\u0131z vard\u0131r: \xc7al\u0131\u015fkan olmak.","Mustafa Kemal Atat\xfcrk",B.cW)
B.Zf=new A.bI("Ba\u015far\u0131, her g\xfcn tekrarlanan k\xfc\xe7\xfck \xe7abalar\u0131n toplam\u0131d\u0131r.","Robert Collier",B.cW)
B.YX=new A.bI("\u0130lham vard\u0131r ama seni \xe7al\u0131\u015f\u0131rken bulmal\u0131d\u0131r.","Pablo Picasso",B.cW)
