B.Zq=new A.bI("Ne ekersen onu bi\xe7ersin.","T\xfcrk atas\xf6z\xfc",B.cW)
B.YN=new A.bI("Bin farkl\u0131 tekmeyi bir kez \xe7al\u0131\u015fandan de\u011fil, tek bir tekmeyi bin kez \xe7al\u0131\u015fandan korkar\u0131m.","Bruce Lee",B.cW)
B.Zo=new A.bI("Hayat\u0131mda defalarca ba\u015far\u0131s\u0131z oldum. \u0130\u015fte bu y\xfczden ba\u015far\u0131l\u0131y\u0131m.","Michael Jordan",B.cW)
B.ei=new A.or("Sab\u0131r",2,"sabir")
